-- Fase 5: backfill zone/sottozone/piante da JSON a Supabase.
-- owner_id: fc227422-ece8-4dca-b706-956ec7ca9e6e (robertagenovese@proton.me, unico account esistente)

insert into zone (id, owner_id, nome, descrizione, esposizione, microclima, criticita, manutenzione, tipo) values
  ('0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Casa', 'Ambiente interno con finestre e terrazzi.', ARRAY['nord','sud','est','ovest']::text[], 'La casa è tendenzialmente umida ed esposta al vento. Non essendo
coibentata, in inverno diventa molto fredda ed è riscaldata tramite
termosifoni in ghisa alimentati a gas. Ad aprile la temperatura è di
circa 18-19°C e l''umidità è al 62%, il riscaldamento è spento.', 'Richiede particolare attenzione
la prevenzione e rimozione della muffa sulle pareti esterne, soprattutto
nei punti più freddi e meno ventilati.', 'Bisogna fare attenzione alla presenza di muffa sul terriccio delle piante in vaso.', 'interno'),
  ('c9bb7211-2380-48b8-8c4b-510dcce7f1a4', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Crinale', 'La zona più grande del giardino. Si sviluppa verso sud fino al confine
con un bosco collinare di proprietà altrui. Sul margine orientale del crinale è presente un muretto a secco rivolto verso est, che curva verso nord fino a raggiungere il confine con il giardino dei vicini.', ARRAY['est','ovest']::text[], 'La posizione di cresta la rende la zona più ventilata del giardino,
esposta ai venti da sud e da nord. Il confine con il bosco collinare
crea un''influenza microambientale: umidità più alta rispetto alle zone
aperte, lettiera di foglie che arricchisce il suolo nel tempo, e
possibile ingresso di specie spontanee dal bosco. In estate la
vegetazione esistente mitiga il calore; in inverno i venti da nord
possono essere intensi.', 'Vento: zona più esposta della proprietà; privilegiare specie robuste con radici profonde Siccità estiva: l’esposizione a sud e il forte irraggiamento prosciugano rapidamente il suolo Invasione di specie spontanee dal bosco: rovi, infestanti e semi trasportati dal vento Parietaria sul muretto: crescita rapida e continua, richiede controllo regolare Accesso e manutenzione: zona ampia e distante dalla casa, richiede tempo e sforzo', 'Questa zona del giardino tende a seccare molto durante l''estate. Bisogna fare attenzione alle infestanti lungo il muretto e lungo il dorso del crinale.', 'esterno'),
  ('21056022-fe98-4bbb-9575-6f9850b4dae4', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Est', 'Lato orientale della proprietà.', ARRAY['est']::text[], 'Sole
diretto dal mattino fino al primo pomeriggio (circa 5–6 ore di sole
diretto). Il pomeriggio la casa proietta ombra parziale su questa zona e il tetto lo ripara dalla pioggia. La collina alle spalle della proprietà funge da schermo naturale per i
venti da nord e nord-ovest, rendendo questa zona relativamente riparata.
Il lato est riceve il sole del mattino con calore progressivo durante
la giornata. Le gelate invernali sono
rare ma possibili (gennaio–febbraio), attenuate dalla massa termica
della collina.', 'Ombra pomeridiana: a seconda dell''altezza della
collina e della vegetazione sul crinale, questa zona potrebbe ricevere
ombra nelle ore tarde; da monitorare in funzione delle piante scelte Suolo asciutto sotto la tettoia: la zona fiorita è
riparata dalla tettoia della casa, che impedisce alla pioggia di
raggiungere direttamente il terreno; il suolo tende a rimanere piuttosto
asciutto e richiede irrigazione supplementare indipendentemente dalle
precipitazioni Umidità persistente al mattino: l''esposizione est
con scarsa ventilazione da ovest può favorire la permanenza della
rugiada e umidità fogliare prolungata, aumentando il rischio di malattie
fungine Escursione termica: la collina riduce la ventilazione notturna, portando a escursioni termiche più marcate rispetto a zone più aperte', 'Accertarsi quotidianamente dello stato di idratazione delle piante fiorite.', 'esterno'),
  ('52dfbafa-56d9-472e-b3b3-856adbd885f7', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Orto', 'Area pianeggiante nella parte est/nord-est della proprietà.', ARRAY['nord','est']::text[], 'Zona relativamente riparata rispetto alle altre aree del giardino grazie
alla posizione arretrata rispetto alla strada e alla presenza di
vegetazione circostante. Il terreno pianeggiante favorisce ristagno
idrico se il drenaggio non è adeguato. Le temperature sono leggermente
più alte rispetto alle zone in pendio grazie alla minore ventilazione.', 'Siccità estiva: il clima adriatico porta estati calde e secche; l''orto necessita di irrigazione regolare da giugno ad agosto Ristagno idrico: il terreno pianeggiante può accumulare acqua in autunno/inverno in caso di piogge intense; verificare il drenaggio Parassiti orticoli: afidi, lumache e nottue sono comuni nelle zone vegetali costiere marchigiane', null, 'esterno'),
  ('9a751a3a-3cfd-462d-86d7-a415d2fe33af', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Scivolo', 'Striscia che si sviluppa da ovest verso est, tra la struttura superiore (garage/dependance) e la casa principale.', ARRAY['est','ovest']::text[], 'La
zona è riparata dal vento grazie alle strutture adiacenti e agli alberi
ai lati. Il pomeriggio estivo porta calore diretto sulla parte centrale
e sul lato sinistro (ovest), che si scalda rapidamente. Il lato destro
ha un microclima distinto: fresco, ombroso e con umidità costantemente
più alta a causa dell''acqua di drenaggio proveniente dalle fioriere
della ringhiera sovrastante. Le temperature su questo lato sono stabili e
più basse rispetto al resto della zona.', 'Calore pomeridiano estivo: il lato sinistro e la
parte centrale possono subire stress da calore nelle ore più calde;
preferire piante resistenti al sole intenso e alla siccità estiva Umidità eccessiva sul lato destro: il drenaggio continuo delle fioriere sovrastanti può portare a ristagno e marciume radicale su specie non adatte all''umidità Luminosità disomogenea: la forte differenza tra il
lato sinistro (soleggiato) e il lato destro (sempre in ombra) richiede
scelte botaniche molto diverse per le due estremità', null, 'esterno'),
  ('a4cff534-c4bc-45fe-8aa0-3e375216aed9', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Vialetto', 'Percorso pedonale sopraelevato che si sviluppa lungo un lato della casa. È composto da due sotto-zone: le fioriere (grandi contenitori in legno lungo il camminamento) e la ringhiera
(piccole fioriere appese alla ringhiera del camminamento). Il drenaggio
delle fioriere scende nella sotto-zona lato-destro dello scivolo
sottostante.', ARRAY['ovest']::text[], 'Caldo e soleggiato nel pomeriggio, con buona ventilazione grazie alla
posizione sopraelevata sul camminamento. Le fioriere in contenitore (sia
grandi che piccole) si scaldano rapidamente e perdono umidità più in
fretta rispetto al terreno aperto. Le fioriere in legno grandi
mantengono l''umidità meglio di quelle piccole in plastica o terracotta.', 'Cacyreus marshalli (farfallina dei gerani):
parassita che depone le uova sui gerani e le cui larve perforano steli e
gemme dall''interno. L''anno scorso ha richiesto una potatura abbondante.
Da monitorare da primavera: trattamenti preventivi con insetticida
specifico o Bacillus thuringiensis all''inizio della stagione Essiccamento rapido: le fioriere, soprattutto
quelle piccole della ringhiera, si asciugano velocemente in estate;
irrigazione frequente indispensabile nelle settimane più calde Stress termico estivo: il calore pomeridiano combinato con substrato limitato può stressare le radici nelle fioriere piccole', 'In estate è richiesta molta irrigazione, a causa dell''esposizione al sole e al vento.', 'esterno');

insert into sottozone (id, owner_id, zona_id, nome, descrizione, esposizione, microclima, criticita, manutenzione, tipo) values
  ('33a3666d-dbc4-486c-8717-015a4c35849e', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Bagni', 'I bagni sono esposti a est. Hanno finestre ma non terrazzi, quindi al momento non è prevista l’aggiunta di piante da esterno. Ricevono molta luce al mattino, durante tutto l’anno.', ARRAY['est']::text[], 'Luce intensa al mattino Umidità elevata, tipica degli ambienti bagno Temperature fresche, soprattutto nei mesi freddi Ventilazione variabile, dipendente dall’apertura delle finestre
Questo microclima è ideale per piante che amano umidità e luce filtrata.', null, 'Irrigazione moderata: evitare ristagni, soprattutto per l’orchidea. Asciugatura foglie: dopo docce calde, asciugare eventuale condensa sulle foglie della pilea. Ventilazione quotidiana per ridurre l’umidità e prevenire muffe. Controllo radici dell’orchidea ogni 6–12 mesi. Pulizia foglie per rimuovere calcare e residui di vapore. Evitare sole diretto nelle ore del mattino se troppo intenso.', 'interno'),
  ('cf356c08-7da7-4db6-87cc-da9d5ddfe2f1', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Cucina', 'In cucina sono presenti due finestre esposte a ovest e un terrazzo esposto a nord/ovest.', ARRAY['nord','ovest']::text[], 'Luce intensa nel pomeriggio grazie alle finestre a ovest Temperature variabili, con tendenza al caldo nelle ore pomeridiane Umidità elevata dovuta alla cottura dei cibi Buona ventilazione grazie al terrazzo e alle finestre apribili
Questo microclima è ideale per molte piante aromatiche e per piante da interno che tollerano luce intensa e umidità variabile.', null, 'Irrigazione regolare per le aromatiche, evitando ristagni. Controllo esposizione: il basilico preferisce luce indiretta nelle ore più calde. Pulizia foglie di dracaena e ceropegia per rimuovere grasso e polvere tipici della cucina. Rotazione dei vasi per garantire crescita uniforme. Monitoraggio parassiti: le aromatiche attirano facilmente afidi e moscerini. Ricambio d’aria quotidiano per ridurre umidità e odori.', 'interno'),
  ('e1b22c9e-af59-4cde-bed7-64576a494299', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Ingresso', 'Lo spazio dell''ingresso dell''appartamento è stretto, non
ha finestre proprie, ma prende luce sia dal bagno ad est che dalla
cucina e soggiorno a ovest.', ARRAY['est','ovest']::text[], null, null, null, 'interno'),
  ('26f99615-e8f4-48a0-8341-65694a236398', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Soggiorno', 'Il soggiorno è una stanza ampia e molto luminosa, con esposizione a ovest.
Durante l’estate il sole pomeridiano la rende particolarmente calda, richiedendo l’uso dell’aria condizionata.
È collegato al terrazzo più grande della casa, che contribuisce alla luminosità e alla ventilazione.', ARRAY['sud','ovest']::text[], 'Molto luminoso nel pomeriggio Tendenza al surriscaldamento estivo Aria secca con aria condizionata Buona ventilazione grazie al terrazzo', null, 'Irrigazione controllata, più frequente in estate. Protezione dal sole diretto nelle ore più calde. Umidificazione leggera per anthurium e bonsai. Controllo parassiti (cocciniglia, acari). Rotazione dei vasi ogni 1–2 settimane. Cambio acqua delle talee ogni 7–10 giorni.', 'interno'),
  ('1d9da149-3217-4a0d-803e-4586fa984ab9', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Scalinata', 'La scalinata è un ambiente fresco e poco illuminato, ma con buona ventilazione.
La luce proviene da due piccole finestre, mentre l’aria circola grazie a
una finestra spesso aperta e al collegamento diretto con il garage.', null, 'Freddo per gran parte dell’anno Luce scarsa Buona ventilazione Umidità moderata', 'Monitoraggio muffe nei mesi più umidi. Attenzione alle correnti d’aria per piante sensibili.', 'Irrigazione minima, solo a terreno completamente asciutto. Pulizia foglie per migliorare la fotosintesi. Controllo radici ogni 6–12 mesi. Rotazione dei vasi ogni 2–3 settimane.', 'interno'),
  ('44210c65-82ed-4f42-acb8-24523169eb4d', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Camera di Marta', null, ARRAY['sud','est']::text[], 'Fresco e umido', 'Tende ad accumulare muffa facilmente, Marta ama fare pasticci e potrebbe non essere affidabile con le piante :-)', 'Controllo e pulizia periodica della muffa.', 'interno'),
  ('36207b25-2acb-4135-920b-8592c49f90d2', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Camera di Paolo', 'Piccolo terrazzo esposto a sud', ARRAY['sud']::text[], null, null, null, 'esterno'),
  ('1e217e71-7e27-4b91-8d98-2b2176bb0c22', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Terrazzo soggiorno', 'Zona esposta a tante ore di luce e molto ventosa', ARRAY['ovest']::text[], null, null, null, 'esterno'),
  ('83676e55-465a-42f7-a795-35e3aec5a517', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', 'Terrazzo cucina', 'Zona ad nord-ovest, soleggiata ma più riparata&nbsp;', ARRAY['nord','ovest']::text[], null, null, null, 'esterno'),
  ('6895a37d-4ded-4710-9223-8e56a8cd49be', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '9a751a3a-3cfd-462d-86d7-a415d2fe33af', 'Lato Destro', 'Sotto-zona orientale dello scivolo. È l''estremità più a est della striscia, adiacente alla zona vialetto/ringhiera. Sempre in ombra: le fioriere soprastanti della zona
vialetto/ringhiera schermano completamente la luce solare diretta. Non
riceve sole né al mattino né al pomeriggio in nessun periodo dell''anno.', ARRAY['est','ovest']::text[], 'Fresco e costantemente umido. Il drenaggio continuo delle fioriere
sovrastanti apporta acqua regolarmente al suolo, mantenendo un''umidità
persistente. È la sotto-zona più fresca e stabile dell''intero scivolo,
con escursioni termiche minime. Le condizioni ricordano un ambiente di
sottobosco.', null, 'Ristagno idrico: l''apporto costante di acqua dalle
fioriere può causare asfissia radicale su specie non adatte; il
drenaggio del suolo è fondamentale Malattie fungine: l''umidità persistente e l''assenza di ventilazione favoriscono muffe e marciumi; evitare piante sensibili Assenza totale di luce diretta: limita fortemente la scelta delle specie; escludere qualsiasi pianta che richieda anche solo mezza ombra', 'esterno'),
  ('70c80906-1eb5-4577-91f0-7d6ddbb0e33c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '9a751a3a-3cfd-462d-86d7-a415d2fe33af', 'Lato Frontale', 'Sotto-zona centrale dello scivolo, posizionata tra il lato sinistro (ovest) e il lato destro (est). Esposizione intermedia: riceve il sole del pomeriggio, ma con minor
intensità rispetto al lato sinistro. La presenza delle strutture
laterali crea una leggera penombra nelle ore mattutine e nelle prime ore
del pomeriggio. È la zona di transizione tra il pieno sole e l''ombra
permanente del lato destro.', ARRAY['ovest']::text[], 'Condizioni bilanciate: né troppo asciutto come il lato sinistro, né
troppo umido come il lato destro. La ventilazione è leggermente più
limitata rispetto alle estremità. Il suolo mantiene una certa freschezza
grazie all''ombra mattutina, pur scaldandosi nel pomeriggio.', 'Variabilità stagionale: le condizioni cambiano
sensibilmente tra estate (caldo pomeridiano diretto) e inverno (ombra
quasi totale); scegliere piante adattabili a entrambe le situazioni Competizione radicale: zona di confine tra microclimi diversi, dove le radici delle piante dei lati adiacenti possono sovrapporsi', null, 'esterno'),
  ('bd10f665-d29f-4da9-9768-4b9f99d79178', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '9a751a3a-3cfd-462d-86d7-a415d2fe33af', 'Lato Sinistro', 'Sotto-zona occidentale dello scivolo. È l''estremità più a ovest della striscia. Riceve
il sole del pomeriggio in modo diretto e prolungato, essendo la parte
più aperta verso ovest. In estate l''irraggiamento pomeridiano è intenso.
Al mattino è in ombra. È la sotto-zona più soleggiata e calda
dell''intero scivolo.', ARRAY['est','ovest']::text[], 'Caldo e asciutto nel pomeriggio estivo. La scarsa ombra e
la buona esposizione al sole fanno evaporare rapidamente l''umidità del
suolo. Riparato dai venti grazie alle strutture adiacenti. Le
temperature possono essere elevate nelle ore pomeridiane estive.', 'Siccità estiva: il calore pomeridiano e la rapida
evaporazione richiedono piante resistenti alla siccità o irrigazione
supplementare nei mesi più caldi Stress termico: nelle giornate più calde le piante delicate possono soffrire per il calore accumulato dalla parete e dal suolo', null, 'esterno'),
  ('28fd2d08-570d-4ad6-959c-1da197adf7d8', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'a4cff534-c4bc-45fe-8aa0-3e375216aed9', 'Fioriere', 'Sotto-zona del vialetto composta da grandi fioriere in legno
disposte lungo il camminamento. Ospita la maggior parte dei gerani e
altre piante da fiore di dimensioni medie. Il drenaggio di queste
fioriere confluisce nella sotto-zona lato-destro dello scivolo
sottostante.', ARRAY['ovest']::text[], 'Molto sole pomeridiano. Le fioriere in
legno, essendo ampie e profonde, permettono un buon sviluppo radicale.
La camelia presente potrebbe preferire una posizione leggermente più
riparata dal sole diretto intenso del pomeriggio estivo. Le
fioriere in legno offrono un buon isolamento termico rispetto ai
contenitori in plastica o terracotta: il substrato si scalda meno
rapidamente e trattiene meglio l''umidità. La posizione sopraelevata sul
camminamento garantisce una buona ventilazione attorno alle piante,
riducendo il rischio di ristagno in superficie.', 'Cacyreus marshalli (farfallina dei gerani): il
parassita principale della zona. Le larve perforano steli e gemme dei
gerani dall''interno, causando avvizzimento e morte dei rami colpiti.
Trattamento preventivo da maggio con insetticida sistemico o Bacillus
thuringiensis Esposizione alle intemperie e al sole eccessivo: in inverno il vento e in estate l''estrema caluria rendono necessarie alcune accortezze', 'Valutare di proteggere le piante presenti in inverno. Prevenzione dai danni di farfallina dei gerani e lumache.', 'esterno'),
  ('61313eb2-b2a3-4c3d-9ae7-ca8ae2280f87', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'a4cff534-c4bc-45fe-8aa0-3e375216aed9', 'Ringhiera', 'Sotto-zona del vialetto composta da piccole fioriere appese alla ringhiera
del camminamento. Il volume ridotto di substrato impone una gestione
più attenta dell''irrigazione rispetto alle grandi fioriere adiacenti. Il
drenaggio scende anch''esso verso il lato-destro dello scivolo
sottostante.', ARRAY['ovest']::text[], 'Molto sole pomeridiano.
Le fioriere appese, essendo sospese e non a contatto col suolo, sono
esposte al sole e al vento su tutti i lati, aumentando ulteriormente la
perdita di umidità. Il
volume ridotto di substrato e la posizione completamente aerea rendono
queste fioriere le più vulnerabili al caldo e alla siccità di tutta la
proprietà. Si scaldano velocemente e si asciugano in poche ore nelle
giornate estive. In inverno possono subire gelate più facilmente
rispetto alle fioriere a terra, essendo esposte anche dal basso all''aria
fredda.', 'Essiccamento rapido: in estate può essere
necessaria irrigazione quotidiana o più volte al giorno; valutare
l''installazione di un sistema di irrigazione a goccia Gelo invernale: le radici delle piante nelle
fioriere appese sono esposte al freddo su tutti i lati; proteggere o
portare al riparo le specie più sensibili in caso di gelate prolungate Peso e stabilità: le fioriere cariche di substrato bagnato esercitano una tensione sulla ringhiera; verificare periodicamente i supporti', null, 'esterno');

insert into piante (id, owner_id, specie, zona_id, sottozona_id, varieta, impianto, impianto_circa, note, coltivato_in, ultima_cura) values
  ('iberis-sempervirens-1776941866176', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'iberis-sempervirens', '21056022-fe98-4bbb-9575-6f9850b4dae4', null, null, null, null, null, 'terra', '{"irrigazione":"2026-08-25","concimazione":"2026-08-20"}'::jsonb),
  ('sansevieria-1777363126334', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'sansevieria', '0c5c2efa-04e6-40a6-92b8-dbaf730cd61c', '1d9da149-3217-4a0d-803e-4586fa984ab9', null, null, null, 'Ha una foglia rovinata nella metà superiore', 'vaso', '{"irrigazione":"2026-07-15","concimazione":"2026-07-15"}'::jsonb),
  ('bellis-perennis-1777363227803', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'bellis-perennis', '21056022-fe98-4bbb-9575-6f9850b4dae4', null, null, '2026-03-02', null, null, 'terra', '{"irrigazione":"2026-08-25","concimazione":"2026-08-20"}'::jsonb),
  ('narciso-1777363322805', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'narciso', '9a751a3a-3cfd-462d-86d7-a415d2fe33af', 'bd10f665-d29f-4da9-9768-4b9f99d79178', null, '2026-03-03', null, null, 'terra', '{"irrigazione":"2026-07-15","concimazione":"2026-07-15"}'::jsonb),
