  ('spiraea-arguta-1777367805928', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'spiraea-arguta', '21056022-fe98-4bbb-9575-6f9850b4dae4', null, null, '2026-03-21', null, 'Ha sofferto molto il trapianto. Ha molti rami secchi, ma sta rigermogliando.', 'terra', '{"irrigazione":"2026-08-25","concimazione":"2026-07-15"}'::jsonb),
